(* [comment removed for export] *)
(* [comment removed for export] *)
Definition msi_segA_post (sp gp tp s2 s3 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (R lo : Z) (s4 s1 s0 ra : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j0 junk,
    ms' = MS (mkR (Z_to_bv 64 P_A_MSI_RET1) (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2
                  (Z_to_bv 64 (bv_unsigned sp + -64)) (Z_to_bv 64 R) (Z_to_bv 64 (bv_unsigned sp + -64)) (Z_to_bv 64 0) (Z_to_bv 64 0) a3 a4 a5 a6 a7
                  s2 s3 (Z_to_bv 64 2147450880) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_SHCOUNT_CTOR_IMPL) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp + -80, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -80)
    /\ rw_cells bsegs m' (bv_unsigned sp + -80) [CB 8 j0; C8 (Z_to_bv 64 0)]
    /\ rw_cells bsegs m' (bv_unsigned sp + -64) [CB 8 junk]
    /\ rw_cells bsegs m' (bv_unsigned sp + -56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

Lemma msi_segA : forall ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (R lo : Z),
  stk bsegs m lo (bv_unsigned sp) -> lo + 80 <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m -> ACONST m ->
  evt bsegs (msi_segA_post sp gp tp s2 s3 s5 s6 s7 s8 s9 s10 s11 F fc R lo s4 s1 s0 ra m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 R) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
